function UIOverseaTowerInsideNode:__init()
    self._vo = nil
    self._cb = nil
    self.friendTrans = nil
end

function UIOverseaTowerInsideNode:__delete()
    self._vo = nil
    self.friendTrans = nil
    self._cb = nil
end

function UIOverseaTowerInsideNode:Awake()
    SetButtonAction(self.Root, Bind(self, self.OnBtnClick))
    CfUtils.SetActive(self.ImgLock3, true)
    self.friendTrans = self.ImgBg.transform:Find("FriendHead")
end

function UIOverseaTowerInsideNode:GetLuaIndex()
    return checkInt(self.luaIndex_)
