function UIOverseaTowerInsideNode:Refresh(id, ind, cb, displayNum, displayCount)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if not vo then
        return
    end

    self._vo = vo
    self._cb = cb
    self._ind = checkNumber(ind)

    self:FillSelect(false)
    if displayNum < displayCount then
        self._co2 = CfUtils.PlayDelayShowAnimate(self.controller.gameObject, displayNum, 0.05, 0.13, "OverseaTowerInsideDialog_List_Cell_Show")
    else
        CfUtils.PlayAnimation(self.controller.gameObject, "UI_Common_List_Cell_Idle")
    end

    self:FillSelf()
    --刷新显示好友的状态
    ---@type TowerQuestComponent
    local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
    local friendDojo = towerQuestComponent:GetTowerFriendInfo(vo.type, vo.refId)
    CfUtils.SetActive(self.friendTrans, not isNull(friendDojo))
    if not isNull(friendDojo) then
        ---@type CommonPlayerHeadNode
        local env = CfUtils.GetLuaScr(self.friendTrans:Find("CommonPlayerHeadNode"), CommonPlayerHeadNode)
        if env then
            env:FreshAvatarFrame(friendDojo.avatar, friendDojo.avatarFrame)
            env:SetCallBack(function()
                if checkNumber(friendDojo.friendId) > 0 then
                    GameUtils.ShowPlayerInfo(checkNumber(friendDojo.friendId), nil)
                end
            end)
        end
    end
end

function UIOverseaTowerInsideNode:FillSelf()
    CfUtils.SetUISwitchImage(self.ImgSymbol1, self._vo.type)
    CfUtils.SetUISwitchImage(self.ImgSymbol2, self._vo.type)
    CfUtils.SetUISwitchText(self.TextDecorate, self._vo.type)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Line, self._vo.type)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_Glow, self._vo.type)

    local isUnlock = OverseaTowerUtils.IsUnlockQuest(self._vo.id)
    local isPass = OverseaTowerUtils.IsPassQuest(self._vo.id)
    CfUtils.SetActive(self.StatusLock, not isUnlock)
    CfUtils.SetActive(self.StatusFinish, isPass)

    local isBoss = (checkNumber(self._vo.monsteType) == 2)
    CfUtils.SetActive(self.TextBoss, isBoss)
    CfUtils.SetActive(self.StatusBoss, isBoss)
    CfUtils.SetActive(self.Reward, isBoss and not isPass)

    CfUtils.FillText(self.TextNormal, self._vo.storey)
    CfUtils.SetActive(self.TextNormal, not isBoss)

    if isBoss then
        if checkNumber(self._vo.type) == Constants.TowerType.Main then
            local floorLevel = checkNumber(self._vo.storey)
            local status = 1
            if floorLevel <= 300 then
                status = 1
            elseif floorLevel > 300 and floorLevel <= 600 then
                status = 5
            elseif floorLevel > 600 and floorLevel <= 900 then
                status = 6
            else
                status = 7
            end
            CfUtils.SetUISwitchImage(self.ImgBoss, status)
            CfUtils.SetUISwitchImage(self.ImgDecorate, status)
            CfUtils.SetUISwitchImage(self.UIFX_ImgDecorate, status)
            CfUtils.SetUISwitchImage(self.ImgAttribute, status)
        else
            CfUtils.SetUISwitchImage(self.ImgBoss, self._vo.type)
            CfUtils.SetUISwitchImage(self.ImgDecorate, self._vo.type)
            CfUtils.SetUISwitchImage(self.UIFX_ImgDecorate, self._vo.type)
            CfUtils.SetUISwitchImage(self.ImgAttribute, self._vo.type)
        end
        CfUtils.FillText(self.TextBoss, self._vo.storey)
        CfUtils.SetActive(self.Reward.transform:Find("ImgBg"), isPass)
        if not isPass then
            local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._vo.id)
            local goodsId = t[1].id
            CfUtils.FillImage(self.ImgGoodsIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId))
        end
    end
end

function UIOverseaTowerInsideNode:FillSelect(isTrue)
    if isTrue then
        CfUtils.PlayDelayShowAnimation(self.Root, 1, "OverseaTowerInsideDialog_Cell_Selected", "OverseaTowerInsideDialog_Cell_Selecting")
    else
        CfUtils.PlayAnimation(self.Root, "OverseaTowerInsideDialog_Cell_UnSelected")
    end

    CfUtils.SetUISwitchImage(self.ImgLock1, isTrue and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgLock4, isTrue and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgLock3, isTrue and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgLock2, isTrue and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgSymbol, isTrue and 2 or 1)
    local isPass = OverseaTowerUtils.IsPassQuest(self._vo.id)

    local status = 1
    if isTrue then
        status = 2
    else
        local isUnlock = OverseaTowerUtils.IsUnlockQuest(self._vo.id)
        if isPass or not isUnlock then
            status = 3
        end
    end
    CfUtils.SetUISwitchText(self.TextNormal, status)
    CfUtils.SetUISwitchText(self.TextBoss, status)
    CfUtils.SetUISwitchText(self.TextDesc2, status)

    status = 1
    if isPass then
        status = isTrue and 2 or 3
    else
        status = isTrue and 2 or 1
    end
    CfUtils.SetUISwitchImage(self.ImgBg, status)
end

function UIOverseaTowerInsideNode:OnBtnClick()
    if not self._cb then
        return
    end

    self._cb()
end

function UIOverseaTowerInsideNode:OnDestroy()
    if self._co2 ~= nil then
        cs_coroutine.stop(self._co2)
        self._co2 = nil
    end

    if self._co ~= nil then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIOverseaTowerInsideNode
